            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-L&#233;gendaires.html&quot; title=&quot;Objets l&#233;gendaires&quot;&gt;Les objets l&#233;gendaires&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Magiques-Mythiques.html&quot; title=&quot;Les objets magiques mythiques&quot;&gt;Les objets magiques mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Mythiques.html&quot; title=&quot;Les sorts mythiques&quot;&gt;Les sorts mythiques&lt;/a&gt;&lt;/li&gt;
